config.schema:
{
  "openapi": "3.1.0",
  "info": {
    "title": "Open-Meteo Weather API",
    "description": "Free weather API, no key required, global coverage.",
    "version": "v1.0.0"
  },
  "servers": [
    {
      "url": "https://api.open-meteo.com",
      "description": "Open-Meteo Public Server"
    }
  ],
  "paths": {
    "/v1/forecast": {
      "get": {
        "description": "Get current weather + forecast by latitude/longitude",
        "operationId": "GetWeatherForecast",
        "parameters": [
          {
            "name": "latitude",
            "in": "query",
            "description": "Latitude (e.g. 32.06 for Nanjing)",
            "required": true,
            "schema": { "type": "number" }
          },
          {
            "name": "longitude",
            "in": "query",
            "description": "Longitude (e.g. 118.78 for Nanjing)",
            "required": true,
            "schema": { "type": "number" }
          },
          {
            "name": "current",
            "in": "query",
            "description": "Return current weather",
            "required": false,
            "schema": { "type": "string", "default": "temperature_2m,relative_humidity_2m,weathercode" }
          }
        ]
      }
    }
  },
  "components": { "schemas": {} }
}
